export type StepType = 'trigger' | 'v1-node' | 'wait' | 'subworkflow' | 'batch';
export type StepConfig = unknown;
export interface BatchStepConfig {
    batchSize: number;
}
export declare function isBatchStepConfig(config: unknown): config is BatchStepConfig;
export interface GraphNode {
    id: string;
    name: string;
    type: StepType;
    config?: StepConfig;
}
export interface GraphEdge {
    from: string;
    to: string;
    outputIndex: number;
    inputIndex: number;
    isBackEdge?: boolean;
}
export interface WorkflowGraph {
    nodes: GraphNode[];
    edges: GraphEdge[];
}
export interface StoredWorkflowGraph extends WorkflowGraph {
    seeded: string[];
}
